import { Match as M, Schema as S } from "effect";
import { Command, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Popover from "../../ui/popover";

const anchor = {
  placement: "bottom-start" as const,
  gap: 4,
  padding: 8,
};

// MODEL

export const Model = S.Struct({
  popover: Popover.Model,
});

export type Model = typeof Model.Type;

// MESSAGE

export const GotPopoverMessage = m("GotPopoverMessage", {
  message: Popover.Message,
});

export const Message = S.Union([GotPopoverMessage]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => {
  const [popover, popoverCommands] = Popover.init({
    id: "popover-animated",
    isAnimated: true,
  });

  return [
    { popover },
    Command.mapMessages(popoverCommands, (message) =>
      GotPopoverMessage({ message })
    ),
  ];
};

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotPopoverMessage: ({ message }) => {
        const [popover, popoverCommands] = Popover.update(
          model.popover,
          message
        );

        return [
          evo(model, { popover: () => popover }),
          Command.mapMessages(popoverCommands, (message) =>
            GotPopoverMessage({ message })
          ),
        ];
      },
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  const toPopoverMessage = (message: Popover.Message): Message =>
    GotPopoverMessage({ message });

  return h.submodel({
    slotId: model.popover.id,
    model: model.popover,
    view: Popover.view,
    viewInputs: {
      anchor,
      toView: (render) =>
        Popover.root<Message>({
          children: [
            Popover.trigger<Message>({
              render,
              label: "Open animated popover",
            }),
            ...(render.isVisible
              ? [
                  Popover.backdrop<Message>({ render }),
                  Popover.panel<Message>({
                    render,
                    children: [
                      h.p(
                        [h.Class("text-sm font-semibold text-gray-900")],
                        ["Animated popover"]
                      ),
                      h.p(
                        [h.Class("mt-2 text-sm text-gray-600")],
                        [
                          "Foldkit keeps the panel mounted while animation state settles.",
                        ]
                      ),
                    ],
                  }),
                ]
              : []),
          ],
        }),
    },
    toParentMessage: toPopoverMessage,
  });
});

import { Scene, Ui } from "foldkit";
import { describe, test } from "vitest";

import * as Popover from "../../ui/popover";
import { GotPopoverMessage, init, update, view } from "./main";

const [initialModel] = init();

const AnchorPopover = Popover.AnchorPopover({
  buttonId: "popover-animated-button",
  anchor: {
    placement: "bottom-start",
    gap: 4,
    padding: 8,
  },
});

const SettlePanelAnimation = Ui.Animation.WaitForAnimationSettled({
  id: "popover-animated-panel",
});

const toAnimationMessage = (message: Ui.Animation.Message) =>
  GotPopoverMessage({ message: Popover.GotAnimationMessage({ message }) });

const resolvePopoverMounts = () =>
  Scene.Mount.resolveAll(
    [
      Popover.PortalPopoverBackdrop,
      Popover.CompletedPortalPopoverBackdrop(),
      (message) => GotPopoverMessage({ message }),
    ],
    [
      AnchorPopover,
      Popover.CompletedAnchorPopover(),
      (message) => GotPopoverMessage({ message }),
    ]
  );

describe("popover-animated example", () => {
  test("opens through the animated popover lifecycle", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(
        Scene.role("button", { name: "Open animated popover" })
      ).toExist(),
      Scene.expect(Scene.text("Animated popover")).not.toExist(),
      Scene.click(Scene.role("button", { name: "Open animated popover" })),
      Scene.Command.expectHas(Ui.Animation.RequestFrame),
      Scene.Command.resolve(
        Ui.Animation.RequestFrame,
        Ui.Animation.AdvancedAnimationFrame(),
        toAnimationMessage
      ),
      resolvePopoverMounts(),
      Scene.Command.resolve(
        SettlePanelAnimation,
        Ui.Animation.EndedAnimation(),
        toAnimationMessage
      ),
      Scene.expect(Scene.text("Animated popover")).toExist(),
      Scene.expect(
        Scene.text(
          "Foldkit keeps the panel mounted while animation state settles."
        )
      ).toExist()
    );
  });
});
